const int kGlyphCount = 184;
inline const Glyph* glyph(uint32_t cp) {
  int lo = 0, hi = kGlyphCount - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (kGlyphs[mid].cp == cp) return &kGlyphs[mid].g;
    if (kGlyphs[mid].cp < cp) lo = mid + 1; else hi = mid - 1;
  }
  return nullptr;
}
